const items = $input.all();

const filtered = items.filter(item => {
  let settings;
  try {
    settings = typeof item.json.notification_settings === 'string'
      ? JSON.parse(item.json.notification_settings)
      : item.json.notification_settings || {};
  } catch (e) {
    return true;
  }

  return settings.weekly_reports !== false;
});

if (filtered.length === 0) return [];
return filtered;

const stats = $input.item.json;
const user = $('Loop Over Users').item.json;

const insights = [];
const recommendations = [];

// Completion rate insights
if (stats.completion_rate >= 85) {
  insights.push(`🌟 Outstanding! ${stats.completion_rate}% completion rate this week.`);
  recommendations.push('Keep up the excellent work! Consider mentoring others.');
} else if (stats.completion_rate >= 60) {
  insights.push(`👍 Good progress — ${stats.completion_rate}% of tasks completed.`);
  recommendations.push('Try batching similar tasks to improve focus.');
} else if (stats.total_tasks > 0) {
  insights.push(`💪 ${stats.completion_rate}% completion rate. Room for improvement!`);
  recommendations.push('Consider breaking large tasks into smaller, manageable chunks.');
}

// On-time rate
if (stats.on_time_rate >= 90) {
  insights.push(`⏰ Excellent punctuality — ${stats.on_time_rate}% on-time rate.`);
} else if (stats.on_time_rate !== null && stats.on_time_rate < 70) {
  insights.push(`📅 ${stats.on_time_rate}% on-time rate. Try padding your deadlines.`);
  recommendations.push('Add 20-30% buffer time to your task estimates.');
}

// AI confidence
if (stats.avg_confidence !== null && stats.avg_confidence < 75) {
  insights.push('💭 Task descriptions could be more specific for better AI suggestions.');
  recommendations.push('Include clear action verbs and context in your task titles.');
}

// Volume and streak
if (stats.total_tasks === 0) {
  insights.push('🚀 No tasks logged this week. Start capturing your to-dos!');
  recommendations.push('Try the email-to-task feature to quickly capture tasks.');
} else if (stats.completed_this_week >= 15) {
  insights.push(`📈 High-volume week — ${stats.completed_this_week} tasks completed!`);
}

if (stats.best_streak >= 7) {
  insights.push(`🔥 Impressive streak: ${stats.best_streak} days of consistent productivity!`);
}

// Productivity level badge
const badges = {
  'top_performer': '🏆 Top Performer',
  'consistent': '📊 Consistent Achiever',
  'building_momentum': '📈 Building Momentum',
  'needs_attention': '🎯 Focus Needed'
};

return [{
  json: {
    user_id: user.id,
    user_name: user.name || 'there',
    user_email: user.email,
    total_tasks: stats.total_tasks || 0,
    completed: stats.completed || 0,
    still_active: stats.still_active || 0,
    on_time_rate: stats.on_time_rate || 0,
    completion_rate: stats.completion_rate || 0,
    high_priority: stats.high_priority || 0,
    avg_confidence: stats.avg_confidence || 0,
    completed_this_week: stats.completed_this_week || 0,
    created_this_week: stats.created_this_week || 0,
    best_streak: stats.best_streak || 0,
    productivity_level: stats.productivity_level,
    badge: badges[stats.productivity_level] || '',
    insights,
    recommendations
  }
}];
